def solve6(g):
    H,W = g.shape
    out = g.copy()
    lab,n = components(g)
    reach = np.zeros((H,W),bool); q=deque()
    for i in range(H):
        for j in (0,W-1):
            if g[i,j]==0 and not reach[i,j]: reach[i,j]=True; q.append((i,j))
    for j in range(W):
        for i in (0,H-1):
            if g[i,j]==0 and not reach[i,j]: reach[i,j]=True; q.append((i,j))
    while q:
        r,c=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            a,b=r+dr,c+dc
            if 0<=a<H and 0<=b<W and g[a,b]==0 and not reach[a,b]:
                reach[a,b]=True; q.append((a,b))
    enclosed = (g==0)&(~reach)
    for k in range(n):
        cells = [tuple(x) for x in np.argwhere(lab==k)]
        D = set(cells)
        rs=[r for r,c in cells]; cs=[c for r,c in cells]
        r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
        best=None
        for a in range(r0,r1+1):
            for b in range(a+1,r1+1):
                for cc in range(c0,c1+1):
                    for d in range(cc+1,c1+1):
                        if (a,cc) in D and (a,d) in D and (b,cc) in D and (b,d) in D:
                            area=(b-a+1)*(d-cc+1)
                            if best is None or area>best[0]: best=(area,a,b,cc,d)
        hints=[]
        if best:
            _,a,b,cc,d = best
            hints=[(r,c) for (r,c) in D if a<r<b and cc<c<d]
        E = [(r,c) for r in range(r0,r1+1) for c in range(c0,c1+1)
             if g[r,c]==0 and enclosed[r,c]]
        if not hints and not E:
            continue
        for (r,c) in E:
            dmin = min(max(abs(r-a2),abs(c-b2)) for (a2,b2) in D)
            out[r,c] = 3 if dmin==1 else 0
        walls = set(D)
        perim = [(r,c) for r in range(r0,r1+1) for c in range(c0,c1+1)
                 if (r==r0 or r==r1 or c==c0 or c==c1)]
        missing = [(r,c) for (r,c) in perim if g[r,c]==0]
        inside0 = [(r,c) for r in range(r0+1,r1) for c in range(c0+1,c1)
                   if g[r,c]==0]
        leak = any(not enclosed[r,c] for (r,c) in inside0)
        if not leak:
            walls |= set(missing)
            for (r,c) in missing:
                out[r,c] = 2
        for r in range(max(0,r0-1),min(H,r1+2)):
            for c in range(max(0,c0-1),min(W,c1+2)):
                if (r,c) in walls or enclosed[r,c]: continue
                if any(max(abs(r-a),abs(c-b))==1 for (a,b) in walls):
                    out[r,c] = 2
    return out

