def corner_rects_max(cells):
    S=set(cells)
    rs=[r for r,c in cells]; cs=[c for r,c in cells]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    best=None
    for ra in range(r0,r1+1):
        for rb in range(ra+1,r1+1):
            for ca in range(c0,c1+1):
                for cb in range(ca+1,c1+1):
                    if all((r,c) in S for r,c in [(ra,ca),(ra,cb),(rb,ca),(rb,cb)]):
                        area=(rb-ra+1)*(cb-ca+1)
                        if best is None or area>best[0]: best=(area,ra,rb,ca,cb)
    return best  # (area, r0,r1,c0,c1) or None

