import numpy as np
from collections import deque

def components(g):
    H,W = g.shape; lab = -np.ones((H,W),int); n=0
    for r in range(H):
        for c in range(W):
            if g[r,c]==1 and lab[r,c]<0:
                q=deque([(r,c)]); lab[r,c]=n
                while q:
                    a,b=q.popleft()
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            x,y=a+dr,b+dc
                            if 0<=x<H and 0<=y<W and g[x,y]==1 and lab[x,y]<0:
                                lab[x,y]=n; q.append((x,y))
                n+=1
    return lab,n

def corner_rects_max(cells):
    cells=set(cells)
