    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    rects=[]
    # find all maximal corner-complete rects: brute force over row/col subsets is too big;
    # use: all pairs of rows that have cells at both c-ranges... simpler: greedy scan
    # For these small comps, enumerate candidate rects from row pairs and col pairs where 4 corners present
    rows=sorted(set(rs)); cols=sorted(set(cs))
    cand=[]
    for i,a in enumerate(rows):
        for b in rows[i:]:
            for j,x in enumerate(cols):
                for y in cols[j:]:
                    if (a,x) in cells and (a,y) in cells and (b,x) in cells and (b,y) in cells:
                        cand.append((a,b,x,y))
